    page = page.replace('<button id="download" type="button" disabled>导出草稿</button>', '<details id="editor-export"><summary>导出草稿（可选）</summary><p>导出保留一份修改文件，不会保存到分析包。</p><button id="download" type="button" disabled>导出草稿</button></details>')
